function relativeSortArray(arr1, arr2) {
  const rank = new Map(arr2.map((v, i) => [v, i]));                    // where each value of arr2 comes
  const key = (v) => (rank.has(v) ? rank.get(v) : arr2.length + v);   // the rest go after, ascending
  return [...arr1].sort((a, b) => key(a) - key(b));
}

def relative_sort_array(arr1, arr2):
    rank = {v: i for i, v in enumerate(arr2)}          # where each value of arr2 comes
    return sorted(arr1, key=lambda v: rank.get(v, len(arr2) + v))   # the rest go after, ascending

int[] relativeSortArray(int[] arr1, int[] arr2) {
    Map<Integer, Integer> rank = new HashMap<>();
    for (int i = 0; i < arr2.length; i++) rank.put(arr2[i], i);       // where each value of arr2 comes
    Integer[] boxed = Arrays.stream(arr1).boxed().toArray(Integer[]::new);
    Arrays.sort(boxed, Comparator.comparingInt(v -> rank.getOrDefault(v, arr2.length + v)));   // the rest go after
    return Arrays.stream(boxed).mapToInt(Integer::intValue).toArray();
}

vector<int> relativeSortArray(vector<int>& arr1, vector<int>& arr2) {
    unordered_map<int, int> rank;
    for (int i = 0; i < (int)arr2.size(); i++) rank[arr2[i]] = i;    // where each value of arr2 comes
    auto key = [&](int v) { return rank.count(v) ? rank[v] : (int)arr2.size() + v; };   // the rest go after
    vector<int> out = arr1;
    sort(out.begin(), out.end(), [&](int a, int b) { return key(a) < key(b); });
    return out;
}

